"use client";

import { forwardRef } from "react";
import { Button, type ButtonProps } from "../button/button";
import { rainbowButtonDefaults, type RainbowButtonSpecProps } from "../generated/rainbow-button.types";
import { cx } from "../utils/cx";
import { motionVars } from "../utils/motion";

export interface RainbowButtonProps extends RainbowButtonSpecProps, Omit<ButtonProps, keyof RainbowButtonSpecProps> {}

/**
 * A button with a multicolour border and a soft glow that travel round it. The label sits on the
 * normal button surface, so its contrast is the plain Button's. Builds on Button.
 */
export const RainbowButton = forwardRef<HTMLButtonElement, RainbowButtonProps>(function RainbowButton(
  {
    children,
    duration = rainbowButtonDefaults.duration,
    isPaused = rainbowButtonDefaults.isPaused,
    variant = rainbowButtonDefaults.variant,
    isDisabled,
    className,
    ...rest
  },
  ref,
) {
  return (
    <span
      data-rdm-paused={isPaused || isDisabled || undefined}
      className={cx("rdm-rainbow inline-flex rounded-[var(--rd-radius-control)] p-0.5", isDisabled && "opacity-50")}
      style={motionVars({ "--rdm-d": `${duration}s` })}
    >
      <span aria-hidden="true" className="rdm-rainbow-glow" />
      <Button
        {...rest}
        ref={ref}
        variant={variant}
        isDisabled={isDisabled}
        className={cx("!border-transparent", variant === "ghost" && "!bg-[var(--rd-color-surface-default)]", className)}
        style={{ borderRadius: "calc(var(--rd-radius-control) - 2px)" }}
      >
        {children}
      </Button>
    </span>
  );
});

// Generated by rdloom codegen from specs/rainbow-button.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

export const rainbowButtonVariantValues = ["primary", "secondary", "ghost", "danger"] as const;
export const rainbowButtonSizeValues = ["sm", "md", "lg"] as const;

/** A button with a multicolour border and soft glow that slowly travels around it. The label sits on the normal button surface, so its contrast is the plain Button's. Builds on Button. */
export interface RainbowButtonSpecProps {
  /**
   * Button label. Icon-only buttons must pass aria-label instead.
   */
  children: ReactNode;
  /**
   * Visual emphasis, as on Button.
   * @default "primary"
   */
  variant?: "primary" | "secondary" | "ghost" | "danger";
  /**
   * Height, padding and font size, as on Button.
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Seconds for one full turn of the colours.
   * @default 4
   */
  duration?: number;
  /**
   * Stops the animation. Moving content that lasts more than five seconds should be stoppable.
   * @default false
   */
  isPaused?: boolean;
  /**
   * Prevents interaction and dims the button.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Shows a spinner and blocks presses; the pending state is announced.
   * @default false
   */
  isLoading?: boolean;
  /**
   * Called when the button is pressed by mouse, touch or keyboard.
   */
  onPress?: () => void;
}

export const rainbowButtonDefaults = {
  variant: "primary",
  size: "md",
  duration: 4,
  isPaused: false,
  isDisabled: false,
  isLoading: false,
} as const;

export const rainbowButtonMeta = {
  "name": "RainbowButton",
  "version": "0.1.0",
  "status": "experimental",
  "role": "button"
} as const;
